CREATE TABLE IF NOT EXISTS mn_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,enabled TINYINT NOT NULL DEFAULT 1,is_admin TINYINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mn_settings (name VARCHAR(80) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mn_codes (user_id BIGINT UNSIGNED PRIMARY KEY,code_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,attempts INT NOT NULL DEFAULT 0,sent_at DATETIME NOT NULL,window_at DATETIME NOT NULL,sends INT NOT NULL DEFAULT 1,FOREIGN KEY(user_id) REFERENCES mn_users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS mn_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,name VARCHAR(160) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,parent_id),FOREIGN KEY(user_id) REFERENCES mn_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mn_notes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NULL,title VARCHAR(255) NOT NULL DEFAULT '',body MEDIUMTEXT NOT NULL,kind ENUM('text','checklist') NOT NULL DEFAULT 'text',pinned TINYINT NOT NULL DEFAULT 0,archived TINYINT NOT NULL DEFAULT 0,trashed_at DATETIME NULL,source_hash CHAR(64) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id,archived,trashed_at,updated_at),INDEX(user_id,source_hash),FULLTEXT KEY search_text(title,body),FOREIGN KEY(user_id) REFERENCES mn_users(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES mn_categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mn_tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,UNIQUE KEY user_tag(user_id,name),FOREIGN KEY(user_id) REFERENCES mn_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mn_note_tags(note_id BIGINT UNSIGNED NOT NULL,tag_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(note_id,tag_id),FOREIGN KEY(note_id) REFERENCES mn_notes(id) ON DELETE CASCADE,FOREIGN KEY(tag_id) REFERENCES mn_tags(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS mn_attachments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,note_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,stored_name CHAR(40) NOT NULL,original_name VARCHAR(255) NOT NULL,mime VARCHAR(120) NOT NULL,size_bytes BIGINT NOT NULL,FOREIGN KEY(note_id) REFERENCES mn_notes(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES mn_users(id) ON DELETE CASCADE) ENGINE=InnoDB;
INSERT IGNORE INTO mn_settings(name,value) VALUES ('session_minutes','10080'),('code_minutes','10'),('max_import_mb','100'),('mail_from','');
